#!/usr/bin/env python3
"""Turn tuned_gains.json (from the dashboard) into include/gains.h for the ESP32 firmware.
Usage:  python3 tools/json_to_gains_h.py tools/tuned_gains.json include/gains.h
JSON keys: "1"=FL, "2"=FR, "3"=RL, "4"=RR; fields P,I,D,F,B = Kp, Ki, Kd, feedforward PWM/rpm, offset PWM."""
import json, os, sys

src = sys.argv[1] if len(sys.argv) > 1 else "tuned_gains.json"
dst = sys.argv[2] if len(sys.argv) > 2 else os.path.join("include", "gains.h")
names = {"1": "FL", "2": "FR", "3": "RL", "4": "RR"}

with open(src) as f:
    g = json.load(f)

lines = [
    "// AUTO-GENERATED by json_to_gains_h.py from " + os.path.basename(src) + " - do not edit by hand.",
    "#pragma once",
    "",
    "struct MotorGains { float kp, ki, kd, ff, off; };  // PWM/rpm, PWM/(rpm*s), -, PWM/rpm, PWM",
    "",
]
for key, name in names.items():
    d = g[key]
    lines.append(f"constexpr MotorGains GAINS_{name} = {{{d['P']}f, {d['I']}f, {d['D']}f, {d['F']}f, {d['B']}f}};")
os.makedirs(os.path.dirname(dst) or ".", exist_ok=True)
with open(dst, "w") as f:
    f.write("\n".join(lines) + "\n")
print(f"wrote {dst}")
